"""Finite owned Windows Selection geometry; immutable source36, separate output, immediate process0."""
from pathlib import Path
import argparse,json,uuid,hashlib,base64
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('manifest',type=Path);p.add_argument('--headless',action='store_true');a=p.parse_args();m=json.loads(a.manifest.read_text());v=json.loads((a.manifest.parent/'windows-stage.json').read_text());assert m['owner']==v['owner']=='preflight'and m['component']==v['component']=='selectionpage'and m['buildExitCode']==0
if not a.headless:assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='preflight'
nonce=uuid.uuid4().hex;o=a.manifest.parent/('headless-windows'if a.headless else'actual-windows-geometry')/nonce;o.mkdir(parents=True);body=(r/'docs/replica/source/selectionpage-windows-cases.json').read_bytes();name='preflight-selectionpage-cases-'+nonce+'.json';(r/'artifacts/replica/windows-download'/name).write_bytes(body)
base="$app=Join-Path (Join-Path $env:TEMP "+q(v['guestFolder'])+") 'app';$out=Join-Path $app "+q('geometry-'+nonce)+";New-Item -ItemType Directory $out|Out-Null;"
code=base+"Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+name)+" -OutFile ($out+'\\cases.json');if((Get-FileHash ($out+'\\cases.json') -Algorithm SHA256).Hash-ne "+q(hashlib.sha256(body).hexdigest().upper())+"){throw 'Cases mismatch'};"
if a.headless:code+="$env:DBMV_HEADLESS='1';$env:DBMV_HEADLESS_SCALE='2';"
code+="try{& ($app+'\\ReplicaProbe.exe') '--selectionpage' ($out+'\\cases.json') $out '--geometry-only';if($LASTEXITCODE-ne0){throw 'Selection geometry failed'};[Convert]::ToBase64String([IO.File]::ReadAllBytes($out+'\\selectionpage-layout.json'))}finally{Remove-Item Env:DBMV_HEADLESS -ErrorAction SilentlyContinue;Remove-Item Env:DBMV_HEADLESS_SCALE -ErrorAction SilentlyContinue};exit 0;"
result=ps(code,timeout=45);(o/'transport.txt').write_text(result);data=base64.b64decode(result.strip().splitlines()[-1]);assert len(json.loads(data)['rows'])==36;(o/'selectionpage-layout.json').write_bytes(data)
cleanup=json.loads(ps("$app=Join-Path (Join-Path $env:TEMP "+q(v['guestFolder'])+") 'app';$p=@(Get-Process ReplicaProbe -ErrorAction SilentlyContinue|Where-Object{$_.Path-eq($app+'\\ReplicaProbe.exe')});@{processCount=$p.Count}|ConvertTo-Json",retry_read=True));assert cleanup['processCount']==0;(o/'cleanup.json').write_text(json.dumps(cleanup));png=ps("$app=Join-Path (Join-Path $env:TEMP "+q(v['guestFolder'])+") 'app';$out=Join-Path $app "+q('geometry-'+nonce)+";[Convert]::ToBase64String([IO.File]::ReadAllBytes($out+'\\selectionpage-rendered.png'))",retry_read=True);(o/'selectionpage-rendered.png').write_bytes(base64.b64decode(png));(o/'environment.json').write_text(json.dumps({'manifest':str(a.manifest),'nonce':nonce,'headless':a.headless,'process0':True}));print(o)
